import java.util.List;

final class Transfers {
    // dest only takes T, src only gives T: the shape of Collections.copy
    static <T> int copyInto(List<? extends T> from, List<? super T> to) {
        for (T x : from) to.add(x);
        return from.size();
    }

    // only writes: ? super
    static <T> void fillWith(List<? super T> target, T value, int count) {
        for (int i = 0; i < count; i++) target.add(value);
    }

    // a read-only parameter still needs ? extends in Java
    static double sumAll(List<? extends Number> amounts) {
        double sum = 0;
        for (Number a : amounts) sum += a.doubleValue();
        return sum;
    }
}

kotlin.src:
// MutableList is invariant, so each function projects it at the use site
fun <T> copyInto(from: MutableList<out T>, to: MutableList<in T>): Int {
    for (x in from) to.add(x)
    return from.size
}

fun <T> fillWith(target: MutableList<in T>, value: T, count: Int) {
    repeat(count) { target.add(value) }
}

// List is declared List<out E>: no projection needed (one would only earn a warning)
fun sumAll(amounts: List<Number>): Double {
    var sum = 0.0
    for (a in amounts) sum += a.toDouble()
    return sum
}

