fun unpack(delivery: MutableList<out Apple>, floor: MutableList<in Apple>): Int {
    var grams = 0
    for (a in delivery) {     // 1. take out: each a is an Apple
        floor.add(a)          // 2. put in: the floor takes Apple or anything above it
        grams += a.grams
    }
    delivery.clear()          // 3. no element in clear(), so the take-only view allows it
    return grams
}

unpack(delivery, floor)       // compiles: 330, and the floor holds the lemon and both apples

